'use strict';

// MODULES //

var tape = require( 'tape' );
var set = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof set, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided an empty tokens array (root pointer), the function returns the value directly', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': 1
	};

	out = set( doc, [], 'beep boop' );
	t.strictEqual( out, 'beep boop', 'returns expected value' );

	out = set( doc, [], 42 );
	t.strictEqual( out, 42, 'returns expected value' );

	out = set( doc, [], null );
	t.strictEqual( out, null, 'returns expected value' );

	t.end();
});

tape( 'the function immutably sets a value at a shallow path', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': 1,
		'b': 2
	};
	expected = {
		'a': 99,
		'b': 2
	};

	out = set( doc, [ 'a' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function immutably sets a value at a deep path', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': {
			'b': {
				'c': 1
			}
		}
	};
	expected = {
		'a': {
			'b': {
				'c': 99
			}
		}
	};

	out = set( doc, [ 'a', 'b', 'c' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );
	t.notEqual( out.a.b, doc.a.b, 'returns expected value' );

	t.end();
});

tape( 'the function uses structural sharing for unchanged subtrees', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': {
				'c': 1
			}
		},
		'd': {
			'e': 2
		}
	};
	out = set( doc, [ 'a', 'b', 'c' ], 99 );

	t.strictEqual( out.d, doc.d, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );

	t.end();
});

tape( 'the function sets a value in an array', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	expected = [ 1, 99, 3 ];

	out = set( doc, [ '1' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function sets a value in nested arrays and objects', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': [{
			'b': 1
		}, {
			'b': 2
		}]
	};
	expected = {
		'a': [{
			'b': 99
		}, {
			'b': 2
		}]
	};

	out = set( doc, [ 'a', '0', 'b' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.strictEqual( out.a[ 1 ], doc.a[ 1 ], 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value along the path' );

	t.end();
});

tape( 'the function throws an error if a token is an unsafe value (prototype pollution vector)', function test( t ) {
	var values;
	var i;

	values = [
		'__proto__',
		'constructor',
		'prototype'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			set( {}, [ value ], 'beep boop' );
		};
	}
});

tape( 'the function throws a type error if an intermediate path segment references a non-traversable value', function test( t ) {
	var values;
	var i;

	values = [
		'',
		42,
		true,
		null
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws when provided ' + ( typeof values[ i ] ) );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			set({
				'a': value
			}, [ 'a', 'b' ], 99 );
		};
	}
});

tape( 'the function adds a new property to an object', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': 1
	};
	expected = {
		'a': 1,
		'b': 2
	};

	out = set( doc, [ 'b' ], 2 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function does not mutate the original document', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': 1
		}
	};
	out = set( doc, [ 'a', 'b' ], 99 );

	t.strictEqual( doc.a.b, 1, 'returns expected value' );
	t.strictEqual( out.a.b, 99, 'returns expected value' );

	t.end();
});
